// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dsptrf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 9', function test( t ) {
	t.strictEqual( dsptrf.length, 9, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if provided an invalid first argument (order)', function test( t ) {
	var values;
	var i;

	values = [
		'foo',
		'bar',
		'',
		1,
		true,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			var IPIV = new Int32Array( 4 );
			var AP = new Float64Array( 10 );
			dsptrf( value, 'upper', 4, AP, 1, 0, IPIV, 1, 0 );
		};
	}
});

