tape( 'the function returns a non-zero status code when a diagonal block is exactly zero (singular matrix)', function test( t ) {
	var expectedIPIV;
	var expectedAP;
	var data;
	var info;
	var IPIV;
	var AP;

	data = COLUMN_MAJOR_UPPER_SINGULAR;

	AP = new Float64Array( data.AP );
	IPIV = new Int32Array( data.IPIV );

	expectedAP = new Float64Array( data.expectedAP );
	expectedIPIV = new Int32Array( data.expectedIPIV );

	info = dsptrf( data.order, data.uplo, data.N, AP, data.strideAP, data.offsetAP, IPIV, data.strideIPIV, data.offsetIPIV ); // eslint-disable-line max-len
	t.strictEqual( info, data.expectedInfo, 'returns expected value' );
	t.strictEqual( info > 0, true, 'returns a positive status code' );
	t.deepEqual( AP, expectedAP, 'returns expected value' );
	t.deepEqual( IPIV, expectedIPIV, 'returns expected value' );

	data = COLUMN_MAJOR_LOWER_SINGULAR;

	AP = new Float64Array( data.AP );
	IPIV = new Int32Array( data.IPIV );

	expectedAP = new Float64Array( data.expectedAP );
	expectedIPIV = new Int32Array( data.expectedIPIV );

	info = dsptrf( data.order, data.uplo, data.N, AP, data.strideAP, data.offsetAP, IPIV, data.strideIPIV, data.offsetIPIV ); // eslint-disable-line max-len
	t.strictEqual( info, data.expectedInfo, 'returns expected value' );
	t.strictEqual( info > 0, true, 'returns a positive status code' );
	t.deepEqual( AP, expectedAP, 'returns expected value' );
	t.deepEqual( IPIV, expectedIPIV, 'returns expected value' );

	t.end();
});

tape( 'the function returns a status code corresponding to the first zero diagonal block which is encountered', function test( t ) {
	var expectedIPIV;
	var expectedAP;
	var data;
	var info;
	var IPIV;
	var AP;

	// When factorizing the upper triangle, columns are processed from `N` to `1`, and, thus, the reported column is the last zero column...
	data = COLUMN_MAJOR_UPPER_MULTIPLE_SINGULAR;

	AP = new Float64Array( data.AP );
	IPIV = new Int32Array( data.IPIV );

	expectedAP = new Float64Array( data.expectedAP );
	expectedIPIV = new Int32Array( data.expectedIPIV );

	info = dsptrf( data.order, data.uplo, data.N, AP, data.strideAP, data.offsetAP, IPIV, data.strideIPIV, data.offsetIPIV ); // eslint-disable-line max-len
	t.strictEqual( info, data.expectedInfo, 'returns expected value' );
	t.deepEqual( AP, expectedAP, 'returns expected value' );
	t.deepEqual( IPIV, expectedIPIV, 'returns expected value' );

	// When factorizing the lower triangle, columns are processed from `1` to `N`, and, thus, the reported column is the first zero column...
	data = COLUMN_MAJOR_LOWER_MULTIPLE_SINGULAR;

	AP = new Float64Array( data.AP );
	IPIV = new Int32Array( data.IPIV );

	expectedAP = new Float64Array( data.expectedAP );
	expectedIPIV = new Int32Array( data.expectedIPIV );

	info = dsptrf( data.order, data.uplo, data.N, AP, data.strideAP, data.offsetAP, IPIV, data.strideIPIV, data.offsetIPIV ); // eslint-disable-line max-len
	t.strictEqual( info, data.expectedInfo, 'returns expected value' );
	t.deepEqual( AP, expectedAP, 'returns expected value' );
	t.deepEqual( IPIV, expectedIPIV, 'returns expected value' );

	t.end();
});

