tape( 'the function leaves the input arrays unchanged when `N` is equal to zero', function test( t ) {
	var expectedIPIV;
	var expectedAP;
	var info;
	var IPIV;
	var AP;

	AP = new Float64Array( [ 1.0, 2.0, 3.0 ] );
	IPIV = new Int32Array( [ 0, 0 ] );

	expectedAP = new Float64Array( [ 1.0, 2.0, 3.0 ] );
	expectedIPIV = new Int32Array( [ 0, 0 ] );

	info = dsptrf( 'column-major', 'upper', 0, AP, 1, 0, IPIV, 1, 0 );
	t.strictEqual( info, 0, 'returns expected value' );
	t.deepEqual( AP, expectedAP, 'returns expected value' );
	t.deepEqual( IPIV, expectedIPIV, 'returns expected value' );

	t.end();
});
